   289→                        <div className="flex items-center gap-3 min-w-0">
   290→                          <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
   291→                            <span className="text-xs font-bold text-primary">
   292→                              {anm.teilnehmerName ? anm.teilnehmerName.charAt(0).toUpperCase() : '?'}
   293→                            </span>
   294→                          </div>
   295→                          <div className="min-w-0">
   296→                            <p className="text-sm font-medium text-foreground truncate">
   297→                              {anm.teilnehmerName || 'Unbekannt'}
   298→                            </p>
   299→                            <p className="text-xs text-muted-foreground">
   300→                              {anm.fields.anmeldedatum ? formatDate(anm.fields.anmeldedatum) : '—'}
   301→                            </p>
   302→                          </div>
   303→                        </div>
   304→                        <div className="flex items-center gap-2 shrink-0">
   305→                          <Badge
   306→                            variant={anm.fields.bezahlt ? 'default' : 'secondary'}
   307→                            className={`text-[10px] px-2 py-0 ${
   308→                              anm.fields.bezahlt
   309→                                ? 'bg-emerald-100 text-emerald-700 border-emerald-200'
   310→                                : 'bg-amber-50 text-amber-700 border-amber-200'
   311→                            }`}
   312→                          >
   313→                            {anm.fields.bezahlt ? (
   314→                              <><CheckCircle2 size={9} className="mr-1" />Bezahlt</>
   315→                            ) : (
   316→                              <><Clock size={9} className="mr-1" />Ausstehend</>
   317→                            )}
   318→                          </Badge>
   319→                          <div className="flex gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
   320→                            <Button
   321→                              variant="ghost"
   322→                              size="sm"
   323→                              className="h-6 w-6 p-0"
   324→                              onClick={() => { setEditingAnmeldung(anm); setShowAnmeldungDialog(true); }}
   325→                            >
   326→                              <Pencil size={11} />
   327→                            </Button>
   328→                            <Button
   329→                              variant="ghost"
   330→                              size="sm"
   331→                              className="h-6 w-6 p-0 text-destructive hover:text-destructive"
   332→                              onClick={() => setDeleteConfirm({ type: 'anmeldung', id: anm.record_id })}
   333→                            >
   334→                              <Trash2 size={11} />
   335→                            </Button>
   336→                          </div>
   337→                        </div>
   338→                      </div>
   339→                    ))}
   340→                  </div>
   341→                )}
   342→              </div>
   343→            </>
   344→          )}
   345→        </div>
   346→      </div>
   347→
   348→      {/* Kurs Dialog */}
   349→      <KursDialog
   350→        open={showKursDialog}
   351→        kurs={editingKurs}
   352→        dozentenMap={dozentenMap}
   353→        raeumeMap={raeumeMap}
   354→        onClose={() => setShowKursDialog(false)}
   355→        onSave={async (fields) => {
   356→          if (editingKurs) {
   357→            await LivingAppsService.updateKurseEntry(editingKurs.record_id, fields);
   358→          } else {
   359→            await LivingAppsService.createKurseEntry(fields);
   360→          }
   361→          fetchAll();
   362→          setShowKursDialog(false);
   363→        }}
   364→      />
   365→
   366→      {/* Anmeldung Dialog */}
   367→      <AnmeldungDialog
   368→        open={showAnmeldungDialog}
   369→        anmeldung={editingAnmeldung}
   370→        selectedKursId={selectedKursId}
   371→        teilnehmerList={teilnehmer}
   372→        onClose={() => setShowAnmeldungDialog(false)}
   373→        onSave={async (fields) => {
   374→          if (editingAnmeldung) {
   375→            await LivingAppsService.updateAnmeldungenEntry(editingAnmeldung.record_id, fields);
   376→          } else {
   377→            await LivingAppsService.createAnmeldungenEntry(fields);
   378→          }
   379→          fetchAll();
   380→          setShowAnmeldungDialog(false);
   381→        }}
   382→      />
   383→
   384→      {/* Delete Confirm */}
   385→      {deleteConfirm && (
   386→        <Dialog open onOpenChange={() => setDeleteConfirm(null)}>
   387→          <DialogContent>
   388→            <DialogHeader>
   389→              <DialogTitle>Löschen bestätigen</DialogTitle>
   390→            </DialogHeader>
   391→            <p className="text-sm text-muted-foreground">
   392→              {deleteConfirm.type === 'kurs'
   393→                ? 'Möchtest du diesen Kurs wirklich löschen? Alle zugehörigen Daten gehen verloren.'
   394→                : 'Möchtest du diese Anmeldung wirklich löschen?'}
   395→            </p>
   396→            <DialogFooter>
   397→              <Button variant="outline" onClick={() => setDeleteConfirm(null)}>Abbrechen</Button>
   398→              <Button
   399→                variant="destructive"
   400→                onClick={async () => {
   401→                  if (deleteConfirm.type === 'kurs') {
   402→                    await LivingAppsService.deleteKurseEntry(deleteConfirm.id);
   403→                    if (selectedKursId === deleteConfirm.id) setSelectedKursId(null);
   404→                  } else {
   405→                    await LivingAppsService.deleteAnmeldungenEntry(deleteConfirm.id);
   406→                  }
   407→                  fetchAll();
   408→                  setDeleteConfirm(null);
   409→                }}
   410→              >
   411→                Löschen
   412→              </Button>
   413→            </DialogFooter>
   414→          </DialogContent>
   415→        </Dialog>
   416→      )}
   417→    </div>
   418→  );
   419→}
