   465→// ─── Kurs Dialog ───────────────────────────────────────────────────────────────
   466→
   467→function KursDialog({
   468→  open,
   469→  kurs,
   470→  dozentenMap,
   471→  raeumeMap,
   472→  onClose,
   473→  onSave,
   474→}: {
   475→  open: boolean;
   476→  kurs: EnrichedKurse | null;
   477→  dozentenMap: Map<string, import('@/types/app').Dozenten>;
   478→  raeumeMap: Map<string, import('@/types/app').Raeume>;
   479→  onClose: () => void;
   480→  onSave: (fields: import('@/types/app').Kurse['fields']) => Promise<void>;
   481→}) {
   482→  const [titel, setTitel] = useState(kurs?.fields.titel ?? '');
   483→  const [beschreibung, setBeschreibung] = useState(kurs?.fields.beschreibung ?? '');
   484→  const [startdatum, setStartdatum] = useState(kurs?.fields.startdatum ?? '');
   485→  const [enddatum, setEnddatum] = useState(kurs?.fields.enddatum ?? '');
   486→  const [maxTeilnehmer, setMaxTeilnehmer] = useState(String(kurs?.fields.max_teilnehmer ?? ''));
   487→  const [preis, setPreis] = useState(String(kurs?.fields.preis ?? ''));
   488→  const [dozentId, setDozentId] = useState(() => {
   489→    if (!kurs?.fields.dozent) return 'none';
   490→    return extractRecordId(kurs.fields.dozent) ?? 'none';
   491→  });
   492→  const [raumId, setRaumId] = useState(() => {
   493→    if (!kurs?.fields.raum) return 'none';
   494→    return extractRecordId(kurs.fields.raum) ?? 'none';
   495→  });
   496→  const [saving, setSaving] = useState(false);
   497→
   498→  // Reset on open
   499→  const handleOpen = () => {
   500→    setTitel(kurs?.fields.titel ?? '');
   501→    setBeschreibung(kurs?.fields.beschreibung ?? '');
   502→    setStartdatum(kurs?.fields.startdatum ?? '');
   503→    setEnddatum(kurs?.fields.enddatum ?? '');
   504→    setMaxTeilnehmer(String(kurs?.fields.max_teilnehmer ?? ''));
   505→    setPreis(String(kurs?.fields.preis ?? ''));
   506→    setDozentId(kurs?.fields.dozent ? extractRecordId(kurs.fields.dozent) ?? 'none' : 'none');
   507→    setRaumId(kurs?.fields.raum ? extractRecordId(kurs.fields.raum) ?? 'none' : 'none');
   508→  };
   509→
   510→  const dozentenList = Array.from(dozentenMap.values());
   511→  const raeumeList = Array.from(raeumeMap.values());
   512→
   513→  const handleSubmit = async () => {
   514→    setSaving(true);
   515→    try {
   516→      const fields: import('@/types/app').Kurse['fields'] = {
   517→        titel: titel || undefined,
   518→        beschreibung: beschreibung || undefined,
   519→        startdatum: startdatum || undefined,
   520→        enddatum: enddatum || undefined,
   521→        max_teilnehmer: maxTeilnehmer ? Number(maxTeilnehmer) : undefined,
   522→        preis: preis ? Number(preis) : undefined,
   523→        dozent: dozentId !== 'none' ? createRecordUrl(APP_IDS.DOZENTEN, dozentId) : undefined,
   524→        raum: raumId !== 'none' ? createRecordUrl(APP_IDS.RAEUME, raumId) : undefined,
   525→      };
   526→      await onSave(fields);
   527→    } finally {
   528→      setSaving(false);
   529→    }
   530→  };
   531→
   532→  return (
   533→    <Dialog open={open} onOpenChange={(o) => { if (!o) onClose(); else handleOpen(); }}>
   534→      <DialogContent className="max-w-md">
   535→        <DialogHeader>
   536→          <DialogTitle>{kurs ? 'Kurs bearbeiten' : 'Neuen Kurs anlegen'}</DialogTitle>
   537→        </DialogHeader>
   538→        <div className="space-y-4 py-2">
   539→          <div className="space-y-1.5">
   540→            <Label>Titel</Label>
   541→            <Input value={titel} onChange={e => setTitel(e.target.value)} placeholder="Kurstitel" />
   542→          </div>
   543→          <div className="space-y-1.5">
   544→            <Label>Beschreibung</Label>
   545→            <Input value={beschreibung} onChange={e => setBeschreibung(e.target.value)} placeholder="Kurzbeschreibung" />
   546→          </div>
   547→          <div className="grid grid-cols-2 gap-3">
   548→            <div className="space-y-1.5">
   549→              <Label>Startdatum</Label>
   550→              <Input type="date" value={startdatum} onChange={e => setStartdatum(e.target.value)} />
   551→            </div>
   552→            <div className="space-y-1.5">
   553→              <Label>Enddatum</Label>
   554→              <Input type="date" value={enddatum} onChange={e => setEnddatum(e.target.value)} />
   555→            </div>
   556→          </div>
   557→          <div className="grid grid-cols-2 gap-3">
   558→            <div className="space-y-1.5">
   559→              <Label>Max. Teilnehmer</Label>
   560→              <Input type="number" value={maxTeilnehmer} onChange={e => setMaxTeilnehmer(e.target.value)} placeholder="z.B. 20" />
   561→            </div>
   562→            <div className="space-y-1.5">
   563→              <Label>Preis (EUR)</Label>
   564→              <Input type="number" value={preis} onChange={e => setPreis(e.target.value)} placeholder="z.B. 199" />
   565→            </div>
   566→          </div>
   567→          <div className="space-y-1.5">
   568→            <Label>Dozent</Label>
   569→            <Select value={dozentId} onValueChange={setDozentId}>
   570→              <SelectTrigger>
   571→                <SelectValue placeholder="Dozent wählen" />
   572→              </SelectTrigger>
   573→              <SelectContent>
   574→                <SelectItem value="none">Kein Dozent</SelectItem>
   575→                {dozentenList.map(d => (
   576→                  <SelectItem key={d.record_id} value={d.record_id}>
   577→                    {d.fields.vorname} {d.fields.nachname}
   578→                  </SelectItem>
   579→                ))}
   580→              </SelectContent>
   581→            </Select>
   582→          </div>
   583→          <div className="space-y-1.5">
   584→            <Label>Raum</Label>
   585→            <Select value={raumId} onValueChange={setRaumId}>
   586→              <SelectTrigger>
   587→                <SelectValue placeholder="Raum wählen" />
   588→              </SelectTrigger>
   589→              <SelectContent>
   590→                <SelectItem value="none">Kein Raum</SelectItem>
   591→                {raeumeList.map(r => (
   592→                  <SelectItem key={r.record_id} value={r.record_id}>
   593→                    {r.fields.raumname}{r.fields.gebaeude ? ` (${r.fields.gebaeude})` : ''}
   594→                  </SelectItem>
   595→                ))}
   596→              </SelectContent>
   597→            </Select>
   598→          </div>
   599→        </div>
   600→        <DialogFooter>
   601→          <Button variant="outline" onClick={onClose} disabled={saving}>Abbrechen</Button>
   602→          <Button onClick={handleSubmit} disabled={saving}>
   603→            {saving ? 'Speichern...' : kurs ? 'Aktualisieren' : 'Anlegen'}
   604→          </Button>
   605→        </DialogFooter>
   606→      </DialogContent>
   607→    </Dialog>
   608→  );
   609→}
   610→
   611→// ─── Anmeldung Dialog ──────────────────────────────────────────────────────────
   612→
   613→function AnmeldungDialog({
   614→  open,
   615→  anmeldung,
   616→  selectedKursId,
   617→  teilnehmerList,
   618→  onClose,
   619→  onSave,
   620→}: {
   621→  open: boolean;
   622→  anmeldung: EnrichedAnmeldungen | null;
   623→  selectedKursId: string | null;
   624→  teilnehmerList: import('@/types/app').Teilnehmer[];
   625→  onClose: () => void;
   626→  onSave: (fields: import('@/types/app').Anmeldungen['fields']) => Promise<void>;
   627→}) {
   628→  const [teilnehmerId, setTeilnehmerId] = useState(() => {
   629→    if (!anmeldung?.fields.teilnehmer) return 'none';
   630→    return extractRecordId(anmeldung.fields.teilnehmer) ?? 'none';
   631→  });
   632→  const [anmeldedatum, setAnmeldedatum] = useState(anmeldung?.fields.anmeldedatum ?? new Date().toISOString().slice(0, 10));
   633→  const [bezahlt, setBezahlt] = useState(String(anmeldung?.fields.bezahlt ?? 'false'));
   634→  const [saving, setSaving] = useState(false);
   635→
   636→  const handleOpen = () => {
   637→    setTeilnehmerId(anmeldung?.fields.teilnehmer ? extractRecordId(anmeldung.fields.teilnehmer) ?? 'none' : 'none');
   638→    setAnmeldedatum(anmeldung?.fields.anmeldedatum ?? new Date().toISOString().slice(0, 10));
   639→    setBezahlt(String(anmeldung?.fields.bezahlt ?? 'false'));
   640→  };
   641→
   642→  const handleSubmit = async () => {
   643→    setSaving(true);
   644→    try {
   645→      const fields: Anmeldungen['fields'] = {
   646→        teilnehmer: teilnehmerId !== 'none' ? createRecordUrl(APP_IDS.TEILNEHMER, teilnehmerId) : undefined,
   647→        kurs: selectedKursId ? createRecordUrl(APP_IDS.KURSE, selectedKursId) : (anmeldung?.fields.kurs ?? undefined),
   648→        anmeldedatum: anmeldedatum || undefined,
   649→        bezahlt: bezahlt === 'true',
   650→      };
   651→      await onSave(fields);
   652→    } finally {
   653→      setSaving(false);
   654→    }
   655→  };
   656→
   657→  return (
   658→    <Dialog open={open} onOpenChange={(o) => { if (!o) onClose(); else handleOpen(); }}>
   659→      <DialogContent className="max-w-sm">
   660→        <DialogHeader>
   661→          <DialogTitle>{anmeldung ? 'Anmeldung bearbeiten' : 'Neue Anmeldung'}</DialogTitle>
   662→        </DialogHeader>
   663→        <div className="space-y-4 py-2">
   664→          <div className="space-y-1.5">
   665→            <Label>Teilnehmer</Label>
   666→            <Select value={teilnehmerId} onValueChange={setTeilnehmerId}>
   667→              <SelectTrigger>
   668→                <SelectValue placeholder="Teilnehmer wählen" />
   669→              </SelectTrigger>
   670→              <SelectContent>
   671→                <SelectItem value="none">Kein Teilnehmer</SelectItem>
   672→                {teilnehmerList.map(t => (
   673→                  <SelectItem key={t.record_id} value={t.record_id}>
   674→                    {t.fields.vorname} {t.fields.nachname}
   675→                  </SelectItem>
   676→                ))}
   677→              </SelectContent>
   678→            </Select>
   679→          </div>
   680→          <div className="space-y-1.5">
   681→            <Label>Anmeldedatum</Label>
   682→            <Input type="date" value={anmeldedatum} onChange={e => setAnmeldedatum(e.target.value)} />
   683→          </div>
   684→          <div className="space-y-1.5">
   685→            <Label>Bezahlt</Label>
   686→            <Select value={bezahlt} onValueChange={setBezahlt}>
   687→              <SelectTrigger>
   688→                <SelectValue />
   689→              </SelectTrigger>
   690→              <SelectContent>
   691→                <SelectItem value="true">Ja — bezahlt</SelectItem>
   692→                <SelectItem value="false">Nein — ausstehend</SelectItem>
   693→              </SelectContent>
   694→            </Select>
   695→          </div>
   696→        </div>
   697→        <DialogFooter>
   698→          <Button variant="outline" onClick={onClose} disabled={saving}>Abbrechen</Button>
   699→          <Button onClick={handleSubmit} disabled={saving}>
   700→            {saving ? 'Speichern...' : anmeldung ? 'Aktualisieren' : 'Anmelden'}
   701→          </Button>
   702→        </DialogFooter>
   703→      </DialogContent>
   704→    </Dialog>
   705→  );
   706→}
   707→
   708→function DashboardSkeleton() {
   709→  return (
   710→    <div className="space-y-6">
   711→      <div className="flex items-center justify-between">
   712→        <Skeleton className="h-8 w-48" />
   713→        <Skeleton className="h-9 w-36" />
   714→      </div>
   715→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   716→        {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
   717→      </div>
   718→      <Skeleton className="h-[480px] rounded-2xl" />
   719→    </div>
