   721→}
   722→
   723→function DashboardError({ error, onRetry }: { error: Error; onRetry: () => void }) {
   724→  return (
   725→    <div className="flex flex-col items-center justify-center py-24 gap-4">
   726→      <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
   727→        <AlertCircle size={22} className="text-destructive" />
   728→      </div>
   729→      <div className="text-center">
